export const blogPostsNewFr: Record<string, BlogPostI18n> = {
  "uffizi-gallery-tickets": { title: "Billets Galerie des Offices 2026 | Prix, Horaire Réservé et Comment Réserver", description: "Guide complet des billets des Offices en 2026. Tous les prix, achat en ligne, bornes automatiques, la vérité sur les files d'attente et astuces d'un local.", h1: "Billets Galerie des Offices 2026 — Prix et Comment Réserver", heroImage: { src: "/images/blog/uffizi-gallery-tickets/hero-uffizi-entrance.webp", alt: "Visiteurs à l'entrée Porte 1 de la Galerie des Offices à Florence", caption: "Porte 1 — l'entrée pour tous les visiteurs individuels de la Galerie des Offices", width: 1200, height: 630 }, sections: [{ heading: "Prix des Billets en un Coup d'Œil", content: "Allons droit aux chiffres. Les prix des billets de la Galerie des Offices pour 2026 :\n\n**Entrée standard (avant 16h), achetée le jour même :** €25\n**Entrée standard (avant 16h), réservée à l'avance :** €29\n**Entrée après-midi (dès 16h), achetée le jour même :** €16\n**Entrée après-midi (dès 16h), réservée à l'avance :** €20\n**Citoyens UE 18-25 ans :** €2 (munissez-vous d'une pièce d'identité)\n**Moins de 18 ans (toute nationalité) :** Gratuit, mais un billet nominatif gratuit reste nécessaire au nom du visiteur\n**Premier dimanche du mois :** Gratuit pour tous, aux Offices et au Corridor de Vasari — un billet nominatif gratuit reste obligatoire, et celui des Offices se retire uniquement au guichet de la billetterie le jour même\n\nOui, acheter au guichet le jour même coûte €4 de moins que réserver à l'avance. Le hic ? Les jours d'affluence, la file au guichet peut durer 1 à 3 heures. En basse saison un jour de semaine, cependant, se présenter et acheter au comptoir ou aux bornes automatiques est une stratégie tout à fait raisonnable.\n\n« À l'avance » signifie simplement acheté avant la date calendaire de votre visite : c'est là que s'appliquent les frais de réservation de €4, d'où les €29 au lieu de €25. Ce que vous payez, c'est un créneau horaire garanti — vous choisissez une heure précise, et à votre arrivée l'attente est considérablement réduite par rapport à la file de la billetterie. Il n'y a pas d'entrée séparée (tout le monde utilise la Porte 1), mais cela réduit significativement le temps d'attente.", image: { src: "/images/blog/uffizi-gallery-tickets/infographic-ticket-prices.webp", alt: "Infographie comparant les prix : en ligne €29, guichet €25, UE 18-25 €2, moins de 18 gratuit", caption: "Prix des billets des Offices 2026 — toutes les options en un coup d'œil" } }, { heading: "Comment Acheter des Billets en Ligne", content: "Acheter en ligne est la méthode la plus populaire. Voici comment :\n\n**Étape 1 :** Visitez le site officiel des Offices (uffizi.it) ou une agence locale indépendante.\n\n**Étape 2 :** Sélectionnez votre date et créneau préféré. Créneaux disponibles toutes les 15 minutes à partir de 8h15. Le créneau de 8h15 est le plus demandé.\n\n**Étape 3 :** Choisissez votre type de billet.\n\n**Étape 4 :** Payez par carte bancaire. Vous recevrez un email de confirmation contenant votre QR code. Ce QR code est le billet : rien à retirer, aucun voucher papier à échanger.\n\n**Étape 5 :** Le jour J, présentez-vous directement à la Porte 1 à votre horaire réservé avec le QR code (sur téléphone, pas besoin d'imprimer) et une pièce d'identité avec photo.\n\n**Combien de temps à l'avance ?** Haute saison (mars-octobre) : au moins 2-3 semaines. Basse saison (novembre-février) : quelques jours suffisent.\n\n**Annulation :** Le site officiel ne rembourse généralement pas. Certains revendeurs proposent l'annulation gratuite jusqu'à 24-48h avant." }, { heading: "Achat au Guichet et Bornes Automatiques", content: "**Le guichet :** Près de la Porte 1. Billets à €25, paiement par carte aux comptoirs. File variable — 10 min en janvier, jusqu'à 2-3h en juillet. Fermeture à 17h30, qui est aussi l'heure de dernière entrée.\n\n**Bornes automatiques :** Dans la zone du guichet. Elles acceptent les espèces et sont plus rapides que la file du comptoir — prévoyez des billets.\n\n**Quand acheter sur place convient :** Jours de semaine en basse saison, plans flexibles.\n**Quand acheter en ligne est mieux :** Haute saison, week-ends, horaire fixe.", image: { src: "/images/blog/uffizi-gallery-tickets/section-ticket-machines.webp", alt: "Bornes automatiques dans le hall de billetterie des Offices", caption: "Les bornes automatiques — plus rapides et même prix (€25)" } }, { heading: "La Vérité sur les Files d'Attente et l'Horaire Réservé", content: "Il n'existe plus de produit « coupe-file » à la Galerie des Offices, et il n'y a jamais eu d'entrée rapide séparée. Tous les visiteurs entrent par la Porte 1 — même porte, même contrôle de sécurité.\n\nCe que vous achetez réellement, c'est un billet à horaire réservé : un créneau garanti (ils partent vite en haute saison) qui vous fait éviter la file d'attente à la billetterie — mais pas l'entrée ni le contrôle.\n\n**Ce qui réduit vraiment l'attente :**\n1. Un créneau réservé et une arrivée ponctuelle à la Porte 1\n2. La Firenze Card — entrée prioritaire qui évite la billetterie (€85 pour 72h)\n3. Venir à 8h15 un mardi de novembre — quasiment pas de file\n\nQuel que soit votre billet, comptez quelques minutes de contrôle de sécurité à la Porte 1 : tout le monde y passe.", image: { src: "/images/blog/uffizi-gallery-tickets/infographic-skip-the-line-truth.webp", alt: "Infographie sur les files d'attente aux Offices : une seule entrée Porte 1, créneau réservé évitant la file de la billetterie", caption: "La réalité : une seule entrée pour tous — réserver un horaire évite la billetterie, pas la porte" } }, { heading: "Informations d'Entrée : Porte 1", content: "**Porte 1 — Tous les Visiteurs :** Côté est, près de l'Arno. Que vous soyez seul ou en groupe organisé, c'est votre entrée.\n**Porte 3 — Plus en service.** D'anciens articles vous y envoient encore pour échanger un voucher ou retirer vos billets : oubliez. Ce système a pris fin en septembre 2025, quand CoopCulture a repris la billetterie des Offices. Plus de vouchers papier, rien à retirer — le QR code de votre email de confirmation est le billet, et vous allez directement à la Porte 1.\n\n**À avoir prêt :** QR code (sur téléphone ou imprimé), pièce d'identité, patience — tout le monde passe le contrôle de sécurité.\n**Bagages :** Les grands sacs doivent être déposés au vestiaire gratuit.", image: { src: "/images/blog/uffizi-gallery-tickets/section-door1-entrance.webp", alt: "Entrée Porte 1 de la Galerie des Offices", caption: "Porte 1 — l'entrée pour tous les visiteurs individuels" } }, { heading: "Entrée Gratuite et Réduite", content: "**Entrée gratuite :** Moins de 18 ans (toute nationalité — gratuit, mais un billet nominatif gratuit reste nécessaire), personnes handicapées + accompagnateur, guides agréés.\n**Entrée réduite (€2) :** Citoyens UE 18-25 ans.\n**Premiers dimanches :** Gratuit pour tous. Files extrêmes. Non recommandé aux visiteurs avec peu de temps." }, { heading: "Astuces pour Économiser", content: "**Achetez au guichet le jour même.** €25 au lieu de €29.\n**Premier dimanche du mois.** Gratuit aux Offices et au Corridor de Vasari, mais bondé. Un billet nominatif gratuit reste obligatoire : celui des Offices se retire au guichet de la billetterie le jour même et n'est pas réservable en ligne.\n**Moins de 18 ? Entrée gratuite.** Vous ne payez rien, mais il faut un billet nominatif gratuit au nom du jeune visiteur.\n**UE 18-25 ?** €2 — valeur exceptionnelle.\n**Firenze Card (€85).** Rentable à partir de 5 musées.\n**Créneaux d'après-midi.** Moins demandés.\n**Comparez les revendeurs.** Certains offrent de meilleurs prix ou l'annulation gratuite.", image: { src: "/images/blog/uffizi-gallery-tickets/infographic-money-saving-tips.webp", alt: "Infographie d'astuces pour économiser", caption: "Comment économiser sur votre visite aux Offices" } }], faq: [{ q: "Combien coûtent les billets des Offices en 2026 ?", a: "€29 réservé à l'avance (incl. €4 de frais) ou €25 au guichet le jour même. Entrée après-midi dès 16h : €20 à l'avance ou €16 le jour même. UE 18-25 : €2. Moins de 18 : gratuit avec billet nominatif. Premier dimanche : gratuit aux Offices et au Corridor de Vasari — un billet nominatif gratuit reste obligatoire, et celui des Offices se retire uniquement au guichet de la billetterie le jour même." }, { q: "Y a-t-il une entrée rapide séparée ?", a: "Non, et le produit coupe-file n'existe plus. Tout le monde entre par la Porte 1. Réserver donne un créneau garanti et évite la file de la billetterie, mais l'entrée et le contrôle de sécurité sont les mêmes pour tous." }, { q: "Peut-on acheter sur place ?", a: "Oui. Guichet à €25. Bornes automatiques aussi. En haute saison : 1-3h d'attente au comptoir." }, { q: "Combien de temps à l'avance réserver ?", a: "Haute saison : 2-3 semaines. Basse saison : quelques jours. Le créneau de 8h15 part toujours en premier." }, { q: "Les billets sont-ils remboursables ?", a: "Ceux du site officiel, généralement non. Certains revendeurs offrent l'annulation gratuite." }] },
  "uffizi-gallery-hours": { title: "Horaires Galerie des Offices 2026 | Ouverture, Fermeture et Nocturnes", description: "Horaires d'ouverture des Offices 2026. Programme quotidien, jours de fermeture, jours fériés, nocturnes et meilleurs horaires pour les files les plus courtes.", h1: "Horaires Galerie des Offices 2026 — Ouverture et Meilleurs Horaires", heroImage: { src: "/images/blog/uffizi-gallery-hours/hero-uffizi-morning.webp", alt: "La Galerie des Offices dans la lumière du matin", caption: "Les Offices à 8h — arrivez tôt pour la meilleure expérience", width: 1200, height: 630 }, sections: [{ heading: "Horaires Standard", content: "**Ouvert :** Mardi au dimanche, 8h15 à 18h30\n**Dernière entrée :** 17h30\n**Fermé :** Tous les lundis\n\nLa galerie ouvre à 8h15 précises. La dernière entrée à 17h30 est strictement appliquée." }, { heading: "Jours de Fermeture et Fériés", content: "**Tous les lundis.** Les Offices et l'Accademia sont fermés le lundi. Alternatives : Palazzo Vecchio, Dôme, Boboli, Oltrarno.\n\n**Fermetures 2026 :** 1er janvier et 25 décembre. Avec les lundis, ce sont les seules fermetures prévues.\n\n**Ouvert les autres jours fériés :** dimanche de Pâques, 1er mai, 2 juin, 15 août (Ferragosto) et 8 décembre, aux horaires habituels.\n\n**25 avril (Fête de la Libération) — ouvert et gratuit :** L'entrée est gratuite pour tous, ce qui en fait l'une des journées les plus fréquentées de l'année. Présentez-vous dès l'ouverture.\n\n**Premier dimanche :** Galerie et Corridor de Vasari ouverts et gratuits. Un billet nominatif gratuit reste obligatoire, et celui des Offices se retire uniquement au guichet de la billetterie le jour même. Foules extrêmes.", image: { src: "/images/blog/uffizi-gallery-hours/infographic-closed-days-2026.webp", alt: "Infographie des jours de fermeture : chaque lundi, 1er janvier et 25 décembre", caption: "Notez ces dates — fermé chaque lundi plus deux jours fériés" } }, { heading: "Nocturnes", content: "En été (juin-septembre), les Offices ouvrent parfois jusqu'à 22h certains soirs (généralement mardis). Dates annoncées au printemps sur uffizi.it. Moins de monde, lumière différente — une des meilleures expériences aux Offices." }, { heading: "Meilleur Horaire d'Arrivée", content: "**8h15 (Ouverture) — LE MEILLEUR :** Les 90 premières minutes sont extraordinaires. La Salle Botticelli presque vide.\n\n**16h00-16h30 — Deuxième meilleur :** Les groupes de jour quittent Florence vers 15h.\n\n**10h00-14h00 — À ÉVITER :** Heures de pointe.\n\n**Mon conseil :** Si vous restez plus d'un jour, visitez les Offices le matin tôt.", image: { src: "/images/blog/uffizi-gallery-hours/infographic-best-worst-times.webp", alt: "Infographie des meilleurs et pires horaires", caption: "8h15 et après 16h sont les créneaux idéaux" } }, { heading: "Combien de Temps Prévoir ?", content: "**Highlights (2h) :** Botticelli, Léonard, Michel-Ange, Raphaël, Titien, Caravage.\n**Visite complète (3-4h) :** La plupart des salles à rythme confortable. Recommandé.\n**Passionnés (4-6h) :** Pour les amateurs d'art sérieux.\n\n**La terrasse panoramique :** Au dernier étage. Vues spectaculaires sur Florence. Ne la manquez pas." }, { heading: "Variations Saisonnières", content: "**Été :** Peut être chaud. Arrivez tôt. Vérifiez les nocturnes.\n**Automne :** Foules diminuent après mi-septembre. Octobre est idéal.\n**Hiver :** Les mois les plus calmes. Salles presque vides.\n**Printemps :** Beau temps attire les foules. Pâques est particulièrement bondée.", image: { src: "/images/blog/uffizi-gallery-hours/infographic-seasonal-crowds.webp", alt: "Infographie de fréquentation mensuelle", caption: "Octobre à février offrent les visites les plus tranquilles" } }], faq: [{ q: "À quelle heure ouvrent les Offices ?", a: "8h15, mardi au dimanche. Fermé les lundis. Dernière entrée 17h30." }, { q: "Les Offices sont-ils ouverts le lundi ?", a: "Non. Fermés chaque lundi de l'année." }, { q: "Combien de temps prévoir ?", a: "2h pour les highlights, 3-4h pour une visite complète." }, { q: "Y a-t-il des nocturnes ?", a: "Parfois en été, jusqu'à 22h les mardis. Dates sur le site officiel." }, { q: "Dernière heure d'entrée ?", a: "17h30 — strictement appliqué." }] },
  "how-to-skip-the-line-uffizi": { title: "Comment Éviter la File aux Offices | 5 Méthodes Prouvées", description: "5 façons honnêtes d'éviter les longues files aux Offices en 2026. Le produit coupe-file n'existe plus — voici ce qui fonctionne vraiment.", h1: "Comment Éviter la File à la Galerie des Offices", heroImage: { src: "/images/blog/how-to-skip-the-line-uffizi/hero-short-queue.webp", alt: "File courte à la Porte 1 des Offices un matin calme", caption: "Un matin calme à la Porte 1 — voilà ce qu'une bonne planification vous offre", width: 1200, height: 630 }, sections: [{ heading: "D'abord, Dissipons un Mythe", content: "Il n'existe plus de billet « coupe-file » aux Offices, et il n'y a jamais eu d'entrée rapide séparée. Tous les visiteurs entrent par la Porte 1 — même porte, même contrôle de sécurité.\n\nCe que vous pouvez réellement éviter, c'est la file d'attente à la billetterie : un billet à horaire réservé vous garantit votre créneau et vous fait passer devant ceux qui doivent encore acheter. Mais personne ne saute l'entrée elle-même — vous vous présentez à la Porte 1 à votre horaire réservé et tout le monde passe un bref contrôle." }, { heading: "1. Réservez un Billet à Horaire Réservé", content: "Le plus efficace. En réservant à l'avance (€29), vous choisissez un créneau garanti et, à l'arrivée, vous allez directement à la Porte 1 au lieu de faire la file à la billetterie. En haute saison : 2-3h sans réservation vs. 15-30 min avec. Gardez le QR code et votre pièce d'identité prêts — rien à retirer.", image: { src: "/images/blog/how-to-skip-the-line-uffizi/section-online-booking.webp", alt: "Smartphone avec réservation en ligne des Offices", caption: "Un billet à horaire réservé — la meilleure façon de réduire l'attente" } }, { heading: "2. Arrivez à 8h15 (L'Ouverture)", content: "Si vous ne suivez qu'un seul conseil : visitez les Offices à 8h15. La galerie est presque vide. Soyez à la Porte 1 à 7h50-8h00. Fonctionne toute l'année." }, { heading: "3. Visitez en Basse Saison (Novembre-Février)", content: "Les mois les plus calmes. Janvier-février : files de 10-30 min même à midi. Octobre et fin septembre : le compromis idéal entre beau temps et foules gérables.", image: { src: "/images/blog/how-to-skip-the-line-uffizi/infographic-monthly-crowds.webp", alt: "Infographie des temps d'attente mensuels", caption: "Les visites hivernales éliminent pratiquement l'attente" } }, { heading: "4. Visitez un Mardi ou Mercredi", content: "**Mardi :** Le meilleur jour. Premier jour après la fermeture du lundi.\n**Mercredi :** Deuxième meilleur.\n**Samedi-dimanche :** Les plus bondés.\n\n**La combinaison idéale :** Mardi 8h15 en basse saison." }, { heading: "5. Utilisez la Firenze Card", content: "€85 pour 72h, entrée prioritaire dans 72+ musées : vous évitez la billetterie, mais vous entrez par la Porte 1 comme tout le monde. Rentable à partir de 5 musées.", image: { src: "/images/blog/how-to-skip-the-line-uffizi/section-firenze-card.webp", alt: "La Firenze Card", caption: "La Firenze Card — entrée prioritaire aux Offices plus 72+ musées pour €85" } }, { heading: "Ce Qui Ne Fonctionne Pas", content: "**Billet 'VIP' ou 'accès rapide' plus cher :** Même entrée Porte 1 qu'avec un billet réservé standard.\n**Arriver super tôt sans billet :** Double file.\n**Chercher une entrée séparée pour les groupes ou les visiteurs sans réservation :** Elle n'existe pas. La Porte 1 est l'unique entrée, pour les individuels comme pour les groupes organisés.\n**Chercher la Porte 3 pour retirer un billet :** Inutile. Depuis la reprise de la billetterie par CoopCulture en septembre 2025, plus de vouchers papier et rien à retirer — votre QR code va directement à la Porte 1.\n**Premier dimanche gratuit :** Le billet gratuit des Offices n'est pas réservable à l'avance — il faut faire la queue au guichet le jour même. Files de 3-4h.\n\n**En résumé :** Horaire réservé + bon timing + saison intelligente = entrée en moins de 5 min." }], faq: [{ q: "Y a-t-il une entrée rapide séparée ?", a: "Non, et le produit coupe-file n'existe plus. Tout le monde passe par la Porte 1. Réserver un horaire garantit le créneau et évite la file de la billetterie, mais l'entrée et le contrôle restent les mêmes." }, { q: "Le moyen le plus rapide d'entrer ?", a: "Un billet à horaire réservé de 8h15 un mardi en basse saison. Entrée en moins de 5 min." }, { q: "Durée de la file sans réservation ?", a: "Haute saison : 2-3h. Basse saison : 10-30 min." }, { q: "La réservation garantit-elle pas de file ?", a: "Non, mais nettement plus courte. Vous évitez la file de la billetterie, mais tout le monde passe le contrôle de sécurité. 15-30 min en pointe, 5 min en heures calmes." }, { q: "La Firenze Card vaut-elle le coup ?", a: "Uniquement si 5+ musées. €85 incluant priorité aux Offices et 72+ musées." }] },
  "uffizi-gallery-map-floor-plan": { title: "Plan et Carte de la Galerie des Offices | Guide Salle par Salle", description: "Naviguez dans les Offices comme un local. Guide salle par salle, emplacements des chefs-d'œuvre, parcours suggérés pour 2h et 4h.", h1: "Plan de la Galerie des Offices — Guide Salle par Salle", heroImage: { src: "/images/blog/uffizi-gallery-map-floor-plan/hero-uffizi-corridor.webp", alt: "Le long couloir de la Galerie des Offices", caption: "Le couloir est des Offices", width: 1200, height: 630 }, sections: [{ heading: "Comprendre la Disposition", content: "Bâtiment en U conçu par Vasari en 1560.\n- **2e étage :** Galeries principales (salles 2-82), couloir avec vue sur l'Arno.\n- **1er étage :** Galeries supplémentaires dont salle 90 (Caravage).\n- **Rez-de-chaussée :** Espaces d'exposition, librairie et sortie.", image: { src: "/images/blog/uffizi-gallery-map-floor-plan/infographic-floor-layout.webp", alt: "Plan simplifié des Offices", caption: "La disposition en U" } }, { heading: "Salles Incontournables", content: "**Salle 2 — Giotto.** **Salles 10-14 — Salle Botticelli** (Naissance de Vénus, Printemps). **Salle 35 — Léonard.** **Salle 38 — Michel-Ange.** **Salle 66 — Raphaël.** **Salle 83 — Titien.** **Salle 90 — Caravage.** **Terrasse panoramique.**", image: { src: "/images/blog/uffizi-gallery-map-floor-plan/infographic-must-see-rooms.webp", alt: "Carte des salles essentielles", caption: "Les salles essentielles" } }, { heading: "Parcours Highlights en 2 Heures", content: "Giotto (5 min) → Botticelli (20 min) → Léonard (10 min) → Michel-Ange (5 min) → Couloir Arno (3 min) → Raphaël (10 min) → Titien (5 min) → Terrasse (15 min) → Caravage (10 min) → Librairie et sortie (25 min)." }], faq: [{ q: "Quelle taille font les Offices ?", a: "Environ 101 salles sur deux étages. Parcours de 2-3 km." }, { q: "Où est la Naissance de Vénus ?", a: "Salles 10-14 (Salle Botticelli), 2e étage." }, { q: "Où est la salle Caravage ?", a: "Salle 90, 1er étage." }, { q: "Y a-t-il une terrasse panoramique ?", a: "Oui. Dernier étage, vues spectaculaires." }, { q: "Peut-on tout voir en 2 heures ?", a: "Les highlights oui, avec un parcours ciblé." }] },
  "famous-paintings-uffizi-gallery": { title: "10 Tableaux Célèbres des Offices à Ne Pas Manquer", description: "Les 10 tableaux incontournables des Offices. Botticelli, Léonard, Michel-Ange, Raphaël, Titien et Caravage.", h1: "10 Tableaux Célèbres des Offices à Ne Pas Manquer", heroImage: { src: "/images/blog/famous-paintings-uffizi-gallery/hero-botticelli-hall.webp", alt: "Visiteurs dans la Salle Botticelli", caption: "La Salle Botticelli — deux des tableaux les plus célèbres au monde", width: 1200, height: 630 }, sections: [{ heading: "Pourquoi Ces 10", content: "Plus de 2 000 tableaux aux Offices. Ces 10 définissent l'expérience. 400 ans d'histoire de l'art, de Giotto à Caravage." }, { heading: "Les 10 Chefs-d'Œuvre", content: "**1. Madone d'Ognissanti — Giotto (salle 2).** **2. Naissance de Vénus — Botticelli (salles 10-14).** **3. Le Printemps — Botticelli (salles 10-14).** **4. L'Annonciation — Léonard (salle 35).** **5. Tondo Doni — Michel-Ange (salle 38).** **6. Madone au Chardonneret — Raphaël (salle 66).** **7. Vénus d'Urbino — Titien (salle 83).** **8. Méduse — Caravage (salle 90).** **9. Adoration des Mages — Gentile da Fabriano (salle 7).** **10. Bacchus — Caravage (salle 90).**", image: { src: "/images/blog/famous-paintings-uffizi-gallery/section-giotto-madonna.webp", alt: "La Madone de Giotto aux Offices", caption: "La Madone de Giotto — le tableau qui a lancé la Renaissance" } }, { heading: "Planifiez Votre Visite", content: "**Durée :** 2-3 heures. **Meilleur moment :** 8h15 mardi ou mercredi. **Billets :** €29 en ligne ou €25 au guichet. **Photos :** Autorisées sans flash." }], faq: [{ q: "Quel est le tableau le plus célèbre ?", a: "La Naissance de Vénus de Botticelli, salles 10-14." }, { q: "Où est la Naissance de Vénus ?", a: "Salles 10-14 (Salle Botticelli), 2e étage." }, { q: "Combien de tableaux aux Offices ?", a: "Plus de 2 000 dans environ 101 salles." }, { q: "Quels artistes sont représentés ?", a: "Giotto, Botticelli, Léonard, Michel-Ange, Raphaël, Titien, Caravage et plus." }, { q: "Peut-on tout voir en une visite ?", a: "Les highlights en 2-3h. Visite complète : 4-6h." }] },
  "caravaggio-uffizi-gallery": { title: "Caravage aux Offices | Méduse, Bacchus et le Sacrifice d'Isaac", description: "Guide des tableaux de Caravage aux Offices. Méduse, Bacchus et Sacrifice d'Isaac — salles, techniques et quoi observer.", h1: "Caravage à la Galerie des Offices", heroImage: { src: "/images/blog/caravaggio-uffizi-gallery/hero-caravaggio-medusa.webp", alt: "Le bouclier de Méduse de Caravage aux Offices", caption: "La Méduse de Caravage — une des images les plus troublantes de l'art occidental", width: 1200, height: 630 }, sections: [{ heading: "Caravage à Florence", content: "Caravage n'a jamais vécu à Florence, mais les Offices abritent trois de ses œuvres majeures dans la salle 90 au 1er étage. Le ténébrisme, les ongles sales, les fruits pourris — Caravage peignait le monde tel qu'il le voyait.", image: { src: "/images/blog/caravaggio-uffizi-gallery/section-room-90.webp", alt: "Salle 90 aux Offices", caption: "Salle 90 — les trois Caravage des Offices" } }, { heading: "Les Trois Chefs-d'Œuvre", content: "**Méduse (1597) :** Un bouclier cérémoniel peint. La surface convexe semble concave — illusion d'optique magistrale. Le modèle était probablement Caravage lui-même.\n\n**Bacchus (ca. 1596-97) :** Le dieu du vin offre un verre au spectateur. Les fruits pourrissent. En 1922, un autoportrait miniature de Caravage fut découvert dans la carafe.\n\n**Sacrifice d'Isaac (ca. 1601-02) :** Isaac hurle de terreur. L'ange saisit le poignet d'Abraham avec une force physique réelle.", image: { src: "/images/blog/caravaggio-uffizi-gallery/section-medusa-detail.webp", alt: "Détail de la Méduse de Caravage", caption: "L'expression de Méduse capture l'instant entre vie et mort" } }, { heading: "Comment Voir Caravage", content: "**Où :** Salle 90, 1er étage. **Meilleur moment :** 8h15 ou après 16h. **Durée :** 20-30 minutes. **Billets :** €29 en ligne ou €25 au guichet." }], faq: [{ q: "Où sont les tableaux de Caravage ?", a: "Salle 90, 1er étage. Méduse, Bacchus et Sacrifice d'Isaac." }, { q: "Combien de tableaux ?", a: "Trois dans la salle 90." }, { q: "Quel est le détail caché dans le Bacchus ?", a: "Un autoportrait miniature dans la carafe de vin. Découvert en 1922." }, { q: "Méduse est un tableau ou un bouclier ?", a: "Les deux. Huile sur bouclier de bois (55 cm de diamètre)." }, { q: "Quelle technique ?", a: "Le ténébrisme — contraste extrême de lumière et d'obscurité." }] },
  "raphael-uffizi-gallery": { title: "Raphaël aux Offices | Madone au Chardonneret et Plus", description: "Guide des tableaux de Raphaël aux Offices. Madone au Chardonneret, portraits et autoportrait.", h1: "Raphaël à la Galerie des Offices", heroImage: { src: "/images/blog/raphael-uffizi-gallery/hero-madonna-goldfinch.webp", alt: "La Madone au Chardonneret de Raphaël aux Offices", caption: "La Madone au Chardonneret — peinte durant les années transformatrices de Raphaël à Florence", width: 1200, height: 630 }, sections: [{ heading: "Raphaël et Florence", content: "Raphaël arriva à Florence vers 1504 à 21 ans. Il apprit le sfumato de Léonard, le dynamisme de Michel-Ange, et créa sa propre synthèse.", image: { src: "/images/blog/raphael-uffizi-gallery/section-raphael-self-portrait.webp", alt: "Autoportrait de Raphaël", caption: "Raphaël — arrivé à 21 ans, reparti comme l'un des plus grands peintres de l'histoire" } }, { heading: "Madone au Chardonneret (1506)", content: "L'œuvre maîtresse de Raphaël aux Offices. Composition pyramidale parfaite. Brisé en 17 morceaux en 1547 et restauré en 2008.", image: { src: "/images/blog/raphael-uffizi-gallery/section-madonna-goldfinch-detail.webp", alt: "Détail de la Madone au Chardonneret", caption: "Le chardonneret symbolise la souffrance future du Christ" } }, { heading: "Comment Voir Raphaël", content: "**Où :** Salle 66, 2e étage. **Durée :** 15-20 min. **Combiner avec :** Galerie Palatine du Palazzo Pitti. **Billets :** €29 ou €25." }], faq: [{ q: "Où sont les tableaux de Raphaël ?", a: "Salle 66, 2e étage." }, { q: "Le plus célèbre ?", a: "La Madone au Chardonneret (1506)." }, { q: "Où d'autre voir Raphaël à Florence ?", a: "Galerie Palatine du Palazzo Pitti." }, { q: "Quand Raphaël a-t-il vécu à Florence ?", a: "Environ 1504-1508. Mort en 1520 à 37 ans." }, { q: "Combien de tableaux ?", a: "Plusieurs, dont la Madone au Chardonneret et le Portrait de Léon X." }] },
  "leonardo-da-vinci-uffizi-gallery": { title: "Léonard de Vinci aux Offices | L'Annonciation et l'Adoration des Mages", description: "Guide des tableaux de Léonard aux Offices. L'Annonciation, l'Adoration des Mages et le Baptême du Christ.", h1: "Léonard de Vinci à la Galerie des Offices", heroImage: { src: "/images/blog/leonardo-da-vinci-uffizi-gallery/hero-annunciation.webp", alt: "L'Annonciation de Léonard aux Offices", caption: "L'Annonciation de Léonard — peinte à peine 20 ans", width: 1200, height: 630 }, sections: [{ heading: "Les Premières Années de Léonard", content: "Né en 1452 à Vinci. Les Offices possèdent trois œuvres de sa période florentine (ca. 1472-1482).", image: { src: "/images/blog/leonardo-da-vinci-uffizi-gallery/section-leonardo-room.webp", alt: "La salle Léonard aux Offices", caption: "Salle 35" } }, { heading: "L'Annonciation (ca. 1472-1475)", content: "Les ailes de l'ange — modelées sur une vraie anatomie d'oiseau — sont une première en peinture. Le paysage se dissout en brume atmosphérique.", image: { src: "/images/blog/leonardo-da-vinci-uffizi-gallery/section-annunciation-detail.webp", alt: "Détail de l'ange Gabriel", caption: "Les ailes de Gabriel basées sur l'anatomie réelle des oiseaux" } }, { heading: "Comment Voir Léonard", content: "**Où :** Salle 35, 2e étage. **Durée :** 15-25 min. **Billets :** €29 ou €25. **Combiner avec :** Musée Galilée (5 min à pied)." }], faq: [{ q: "Où sont les tableaux de Léonard ?", a: "Salle 35, 2e étage." }, { q: "Combien de tableaux ?", a: "Trois : l'Annonciation, l'Adoration des Mages (inachevée) et contribution au Baptême du Christ." }, { q: "Pourquoi l'Adoration est-elle inachevée ?", a: "Léonard quitta Florence pour Milan en 1481." }, { q: "Qu'est-ce que le sfumato ?", a: "Technique de couches translucides pour des transitions douces entre lumière et ombre." }, { q: "Léonard a-t-il vraiment peint dans le Baptême ?", a: "Oui — au moins l'ange de gauche et des parties du paysage." }] },
  "botticelli-primavera-uffizi": { title: "Le Printemps de Botticelli | Signification, Symbolisme et Guide", description: "Guide complet du Printemps de Botticelli aux Offices. Les 9 figures expliquées, symbolisme, les 500 espèces de plantes.", h1: "Le Printemps de Botticelli — Signification et Symbolisme", heroImage: { src: "/images/blog/botticelli-primavera-uffizi/hero-primavera-full.webp", alt: "Le Printemps de Botticelli complet aux Offices", caption: "Le Printemps de Botticelli (ca. 1480) — le tableau le plus analysé de la Renaissance", width: 1200, height: 630 }, sections: [{ heading: "Le Tableau en un Coup d'Œil", content: "Salles 10-14 (Salle Botticelli), face à la Naissance de Vénus. Neuf figures mythologiques dans une orangeraie. Se lit de droite à gauche : Zéphyr poursuit Chloris qui se transforme en Flore. Au centre Vénus, au-dessus Cupidon. À gauche les Trois Grâces et Mercure.", image: { src: "/images/blog/botticelli-primavera-uffizi/section-primavera-overview.webp", alt: "Les neuf figures du Printemps", caption: "Les neuf figures, de droite à gauche" } }, { heading: "Que Signifie-t-il ?", content: "Pas d'interprétation unique acceptée. Allégorie néoplatonicienne, célébration du printemps, tableau de mariage — probablement tout à la fois." }, { heading: "Comment Voir Le Printemps", content: "**Où :** Salles 10-14, 2e étage. **Meilleur moment :** 8h15 mardi ou mercredi. **Durée :** 10-15 min pour le Printemps, 30-45 min pour toute la salle. **Billets :** €29 ou €25." }], faq: [{ q: "Que signifie Le Printemps ?", a: "Pas d'interprétation unique. La plus courante : allégorie néoplatonicienne." }, { q: "Où est-il ?", a: "Salles 10-14, 2e étage. Face à la Naissance de Vénus." }, { q: "Combien de figures ?", a: "Neuf : Zéphyr, Chloris, Flore, Vénus, Cupidon, les Trois Grâces et Mercure." }, { q: "Combien d'espèces de plantes ?", a: "Environ 500, au moins 190 identifiées. Toutes réelles de Toscane." }, { q: "Quand a-t-il été peint ?", a: "Vers 1480." }] },
  "medici-family-uffizi-gallery": { title: "Les Médicis et la Galerie des Offices | Comment Florence Obtint Son Plus Grand Musée", description: "L'histoire des Médicis et des Offices. Le Pacte d'Anna Maria Luisa de 1737 qui garda tout à Florence.", h1: "Les Médicis et la Galerie des Offices", heroImage: { src: "/images/blog/medici-family-uffizi-gallery/hero-uffizi-exterior.webp", alt: "L'extérieur des Offices avec l'architecture de Vasari", caption: "Les Offices — construits par Vasari pour Cosme Ier de Médicis en 1560", width: 1200, height: 630 }, sections: [{ heading: "La Famille qui a Fait Florence", content: "Pendant près de 300 ans (1434-1737), les Médicis ont dominé Florence — banquiers, politiciens, papes et grands-ducs. Ils ont commandé le dôme de Brunelleschi, soutenu Botticelli et Michel-Ange, et construit les Offices.", image: { src: "/images/blog/medici-family-uffizi-gallery/section-medici-coat-of-arms.webp", alt: "Les armes des Médicis aux Offices", caption: "Les palle des Médicis — visibles partout aux Offices" } }, { heading: "Le Pacte d'Anna Maria Luisa (1737)", content: "Le moment le plus important de l'histoire des Offices. Quand le dernier grand-duc Médicis mourut en 1737, Anna Maria Luisa négocia que toute la collection reste à Florence pour toujours, accessible au public.\n\nSans ce document, la Naissance de Vénus pourrait être à Vienne. Les Offices tels que nous les connaissons n'existeraient pas.", image: { src: "/images/blog/medici-family-uffizi-gallery/section-anna-maria-luisa.webp", alt: "Portrait d'Anna Maria Luisa de' Médicis", caption: "La femme qui a assuré que la collection reste à Florence pour toujours" } }], faq: [{ q: "Qui a construit les Offices ?", a: "Cosme Ier en 1560, conçus par Vasari. Bureaux à l'origine, convertis en musée depuis 1581." }, { q: "Qu'est-ce que le Pacte d'Anna Maria Luisa ?", a: "Un accord de 1737 garantissant que toute la collection reste à Florence pour toujours." }, { q: "Quand sont-ils devenus un musée public ?", a: "Formellement en 1769." }, { q: "Où d'autre voir l'histoire des Médicis ?", a: "Palazzo Pitti, Chapelles des Médicis, Palazzo Vecchio, Jardin de Boboli, Corridor de Vasari." }, { q: "Pourquoi tant d'art ?", a: "Passion et outil politique pour renforcer leur prestige." }] },
  "vasari-corridor-florence": { title: "Corridor de Vasari Florence 2026 | Billets et Que Voir", description: "Guide du Corridor de Vasari. Histoire, visite 2026, billets et conseils.", h1: "Corridor de Vasari Florence 2026", heroImage: { src: "/images/blog/vasari-corridor-florence/hero-corridor-exterior.webp", alt: "Le Corridor de Vasari au-dessus du Ponte Vecchio", caption: "Le Corridor de Vasari — le passage privé des Médicis", width: 1200, height: 630 }, sections: [{ heading: "Qu'est-ce que le Corridor de Vasari ?", content: "Un passage surélevé couvert de 760 mètres du Palazzo Vecchio à travers les Offices, au-dessus du Ponte Vecchio, jusqu'au Palazzo Pitti. Construit en cinq mois en 1565.", image: { src: "/images/blog/vasari-corridor-florence/section-corridor-map.webp", alt: "Plan du Corridor", caption: "Le parcours — 760 mètres" } }, { heading: "Visite 2026", content: "Non inclus dans le billet standard des Offices. Uniquement en visite guidée (45-60 min, groupes de max. 25). €45-90 par personne. Réserver sur uffizi.it.", image: { src: "/images/blog/vasari-corridor-florence/section-corridor-interior.webp", alt: "Intérieur du Corridor", caption: "À l'intérieur du Corridor" } }], faq: [{ q: "Peut-on le parcourir ?", a: "Oui, uniquement en visite guidée." }, { q: "Quelle longueur ?", a: "760 mètres. Visites de 45-60 min." }, { q: "Combien coûtent les billets ?", a: "€45-90 par personne." }, { q: "Pourquoi a-t-il été construit ?", a: "En 1565 pour le mariage du fils de Cosme Ier avec Jeanne d'Autriche." }, { q: "Est-il ouvert en 2026 ?", a: "Consultez uffizi.it." }] },
  "one-day-in-florence-itinerary": { title: "Florence en Un Jour | L'Itinéraire Parfait 2026", description: "L'itinéraire parfait d'une journée à Florence. Heure par heure : Offices, Dôme, Accademia, Ponte Vecchio, coucher de soleil et dîner.", h1: "Florence en Un Jour — L'Itinéraire Parfait", heroImage: { src: "/images/blog/one-day-in-florence-itinerary/hero-florence-panorama.webp", alt: "Vue panoramique de Florence depuis le Piazzale Michelangelo", caption: "Florence en un jour — ambitieux mais faisable", width: 1200, height: 630 }, sections: [{ heading: "Peut-on Voir Florence en Un Jour ?", content: "Soyons honnêtes : un jour ne suffit pas. Mais si c'est tout ce que vous avez, vous pouvez voir énormément.\n\n**Réservez à l'avance** les Offices (créneau 8h15) et l'Accademia en ligne.\n\n**Budget :** ~€75-110 par personne. Moins de 18 : musées gratuits.", image: { src: "/images/blog/one-day-in-florence-itinerary/infographic-day-overview.webp", alt: "Infographie de la journée", caption: "Votre journée en un coup d'œil" } }, { heading: "8h15 — Galerie des Offices (2-2,5h)", content: "Parcours highlights : Giotto → Botticelli → Léonard → Michel-Ange → Raphaël → Titien → Terrasse → Caravage. Sortie vers 10h30.", image: { src: "/images/blog/one-day-in-florence-itinerary/section-uffizi-morning.webp", alt: "Les Offices tôt le matin", caption: "Les Offices à 8h30" } }, { heading: "17h30 — Coucher de Soleil au Piazzale Michelangelo et Dîner", content: "Le plus beau point de vue de Florence. Apportez du vin et des amuse-bouches. Pour le dîner : bistecca alla fiorentina ou pappardelle al cinghiale avec un Chianti Classico.", image: { src: "/images/blog/one-day-in-florence-itinerary/section-piazzale-sunset.webp", alt: "Coucher de soleil depuis le Piazzale", caption: "La fin parfaite d'une journée à Florence" } }], faq: [{ q: "Peut-on voir Florence en un jour ?", a: "Les incontournables oui — Offices, Dôme, Accademia, Ponte Vecchio et coucher de soleil." }, { q: "Combien coûte un jour ?", a: "~€75-110. Moins de 18 : musées gratuits." }, { q: "Faut-il réserver ?", a: "Oui, indispensable." }, { q: "Que sauter si peu de temps ?", a: "Montée au dôme, Museo dell'Opera, intérieur du Palazzo Pitti." }, { q: "Florence est-elle praticable à pied ?", a: "Absolument. Centre compact — tout à 15 min à pied." }] },
  "3-days-in-florence-itinerary": { title: "3 Jours à Florence | L'Itinéraire Ultime", description: "Itinéraire parfait de 3 jours à Florence. Jour par jour avec musées, gastronomie, quartiers et vues.", h1: "3 Jours à Florence — L'Itinéraire Ultime", heroImage: { src: "/images/blog/3-days-in-florence-itinerary/hero-florence-rooftops.webp", alt: "Toits de Florence avec le Dôme", caption: "Trois jours — assez pour tomber amoureux de cette ville", width: 1200, height: 630 }, sections: [{ heading: "Pourquoi 3 Jours", content: "Jour 1 : Art (Offices + Accademia). Jour 2 : Architecture, jardins et Oltrarno. Jour 3 : Petits musées et exploration.\n\n**Budget total (par personne) :** Musées €80-130, repas €90-180.", image: { src: "/images/blog/3-days-in-florence-itinerary/infographic-3-day-overview.webp", alt: "Infographie 3 jours", caption: "Trois jours, trois thèmes" } }, { heading: "Astuces pour Économiser", content: "**Firenze Card (€85) :** Couvre €135+ d'entrées. Économie de €50.\n**Moins de 18 :** Gratuit partout.\n**UE 18-25 :** €2.\n**Gratuit :** Piazza della Signoria, Ponte Vecchio, Dôme intérieur, Piazzale Michelangelo." }], faq: [{ q: "3 jours suffisent-ils ?", a: "Oui — musées principaux, Dôme, quartiers clés et bonne cuisine." }, { q: "Combien coûtent 3 jours ?", a: "~€250-400 sans hébergement." }, { q: "Meilleur quartier ?", a: "Oltrarno — ambiance authentique, bons restaurants." }, { q: "Firenze Card ?", a: "Oui pour 3 jours intensifs de musées." }, { q: "Excursions ?", a: "Concentrez-vous sur Florence. Alternative : demi-journée à Fiesole." }] },
  "florence-walking-tour-self-guided": { title: "Visite à Pied de Florence Autoguidée | Parcours Gratuit", description: "Visite autoguidée gratuite de Florence. 10 étapes, 2-3 heures, sans réservation.", h1: "Visite à Pied de Florence — Parcours Autoguidé Gratuit", heroImage: { src: "/images/blog/florence-walking-tour-self-guided/hero-florence-street.webp", alt: "Une rue étroite de Florence", caption: "Florence se vit à pied", width: 1200, height: 630 }, sections: [{ heading: "Avant de Partir", content: "10 étapes, ~3,5 km, 2-3 heures. Pas de billets nécessaires.\n\nParcours : Gare → Santa Maria Novella → Via dei Tornabuoni → Piazza della Repubblica → Orsanmichele → Piazza della Signoria → Dôme → Ponte Vecchio → Oltrarno → Piazzale Michelangelo (optionnel)", image: { src: "/images/blog/florence-walking-tour-self-guided/infographic-walking-route.webp", alt: "Carte du parcours", caption: "Le parcours complet de 10 étapes" } }, { heading: "Conseils de Marche", content: "**Perdez-vous volontairement.** Le charme de Florence est dans les ruelles.\n**Chaussures confortables.** Pavés inégaux.\n**Fontaines publiques.** Eau gratuite partout.\n**Culture du café.** Au comptoir : €1-1,50. Assis : €3-6." }], faq: [{ q: "Combien de temps ?", a: "2-3 heures, ~3,5 km." }, { q: "Florence est-elle facile à pied ?", a: "Très. Centre compact et piéton." }, { q: "Billets nécessaires ?", a: "Non pour les étapes extérieures." }, { q: "Meilleur moment ?", a: "Tôt le matin ou en fin d'après-midi." }, { q: "Adapté aux enfants ?", a: "Oui. Parcours plat sauf l'extension au Piazzale." }] },
  "palazzo-pitti-florence": { title: "Palazzo Pitti Florence 2026 | Billets, Que Voir et Ça Vaut le Coup ?", description: "Guide du Palazzo Pitti. Les 4 musées, œuvres de Raphaël et Titien, billets et avis.", h1: "Palazzo Pitti Florence 2026", heroImage: { src: "/images/blog/palazzo-pitti-florence/hero-pitti-facade.webp", alt: "La façade du Palazzo Pitti", caption: "Palazzo Pitti — la résidence des Médicis", width: 1200, height: 630 }, sections: [{ heading: "Qu'est-ce que le Palazzo Pitti ?", content: "Un immense palais Renaissance au sud de l'Arno. 4 musées et le Jardin de Boboli. Bien moins visité que les Offices mais art de premier plan. 11 Raphaëls et 8 Titiens.", image: { src: "/images/blog/palazzo-pitti-florence/section-pitti-interior.webp", alt: "Intérieur de la Galerie Palatine", caption: "La Galerie Palatine" } }, { heading: "Ça Vaut le Coup ?", content: "**Oui si :** Vous aimez Raphaël, avez déjà vu les Offices, voulez combiner avec Boboli.\n**Peut-être pas si :** Un seul jour à Florence (priorité Offices et Accademia).\n\n**Billets :** €16 Galerie Palatine. Moins de 18 gratuit.", image: { src: "/images/blog/palazzo-pitti-florence/section-pitti-garden-view.webp", alt: "Vue sur le Jardin de Boboli", caption: "Combinaison parfaite pour une demi-journée" } }], faq: [{ q: "Prix des billets ?", a: "€16 Galerie Palatine. Boboli €10 séparé. Moins de 18 gratuit." }, { q: "Ça vaut le coup ?", a: "Absolument. 11 Raphaëls, 8 Titiens, peu de monde." }, { q: "Combien de temps ?", a: "1,5-2h galerie + 1-2h Boboli." }, { q: "C'est la même chose que les Offices ?", a: "Non. Musées séparés, ~10 min à pied via le Ponte Vecchio." }, { q: "Horaires ?", a: "Mardi-dimanche 8h15-18h30. Fermé le lundi." }] },
  "boboli-gardens-florence": { title: "Jardin de Boboli Florence | Billets, Horaires et Que Voir 2026", description: "Guide du Jardin de Boboli. Que voir, meilleur parcours, billets et horaires. À combiner avec le Palazzo Pitti.", h1: "Jardin de Boboli Florence — Billets, Horaires et Que Voir", heroImage: { src: "/images/blog/boboli-gardens-florence/hero-boboli-amphitheater.webp", alt: "L'Amphithéâtre du Jardin de Boboli", caption: "L'Amphithéâtre de Boboli", width: 1200, height: 630 }, sections: [{ heading: "Qu'est-ce que le Jardin de Boboli ?", content: "Un des premiers et plus importants jardins Renaissance italiens. 45 000 m² derrière le Palazzo Pitti. Parc public et musée en plein air." }, { heading: "Ça Vaut le Coup ?", content: "**Oui si :** Vous aimez les jardins, besoin d'une pause des musées, visitez le Palazzo Pitti, voulez des vues panoramiques ou voyagez avec des enfants.\n\n**Durée :** 1,5-2 heures. Chaussures confortables." }], faq: [{ q: "Prix des billets ?", a: "€10. Moins de 18 gratuit. UE 18-25 €2. Gratuit premier dimanche." }, { q: "Combien de temps ?", a: "1,5-2 heures." }, { q: "Horaires ?", a: "8h15-18h30. Fermé premier et dernier lundi du mois." }, { q: "Ça vaut le coup ?", a: "Oui — surtout combiné avec le Palazzo Pitti." }, { q: "Peut-on apporter de la nourriture ?", a: "Oui. Apportez eau et en-cas." }] },
  "ponte-vecchio-florence": { title: "Ponte Vecchio Florence | Histoire, Boutiques et Meilleurs Points Photo", description: "Guide du Ponte Vecchio. Histoire depuis 1345, orfèvres, le Corridor de Vasari et les meilleurs spots photo.", h1: "Ponte Vecchio Florence — Histoire, Boutiques et Photos", heroImage: { src: "/images/blog/ponte-vecchio-florence/hero-ponte-vecchio-sunset.webp", alt: "Le Ponte Vecchio au coucher de soleil", caption: "Le Ponte Vecchio au coucher de soleil — la vue la plus iconique de Florence", width: 1200, height: 630 }, sections: [{ heading: "Un Pont Unique au Monde", content: "Le pont le plus célèbre du monde, le seul de Florence à avoir survécu à la Seconde Guerre mondiale. Structure actuelle de 1345. ~40 boutiques d'orfèvres. Le Corridor de Vasari passe au-dessus. Gratuit, ouvert 24h." }, { heading: "Meilleurs Points Photo", content: "**1. Ponte Santa Trinita (LE MEILLEUR) :** Un pont à l'ouest. Vue classique au coucher de soleil.\n**2. Terrasse des Offices :** Vue surélevée.\n**3. Depuis l'Oltrarno :** Vue avec skyline.", image: { src: "/images/blog/ponte-vecchio-florence/section-photo-spots.webp", alt: "Vue classique du Ponte Vecchio", caption: "La photo définitive du Ponte Vecchio" } }], faq: [{ q: "Pourquoi est-il célèbre ?", a: "Le plus ancien pont de Florence (1345), orfèvres depuis 1593, seul pont survivant de la WWII." }, { q: "Est-il gratuit ?", a: "Oui. Ouvert 24h. Boutiques ~10h-19h, fermées dimanche." }, { q: "Meilleur spot photo ?", a: "Ponte Santa Trinita au coucher de soleil." }, { q: "Qu'est-ce que le Corridor de Vasari ?", a: "Passage surélevé de 1565 des Médicis au-dessus des boutiques." }, { q: "Pourquoi que des orfèvres ?", a: "En 1593, Ferdinand Ier expulsa les bouchers à cause de l'odeur." }] },
  "florence-cathedral-duomo-guide": { title: "Cathédrale de Florence (Dôme) Guide 2026 | Montée au Dôme, Billets et Conseils", description: "Guide du Dôme de Florence 2026. Montée au dôme de Brunelleschi, Campanile de Giotto, Baptistère, billets (€30 combo) et code vestimentaire.", h1: "Cathédrale de Florence (Dôme) Guide 2026", heroImage: { src: "/images/blog/florence-cathedral-duomo-guide/hero-duomo-dome.webp", alt: "La Cathédrale de Florence avec le dôme rouge de Brunelleschi", caption: "Le dôme de Brunelleschi — la merveille d'ingénierie qui a changé l'architecture", width: 1200, height: 630 }, sections: [{ heading: "Le Dôme en un Coup d'Œil", content: "Le plus grand dôme en maçonnerie jamais construit (45 m de diamètre). Le complexe comprend : cathédrale, dôme, Campanile de Giotto, Baptistère et Museo dell'Opera.\n\nCathédrale : gratuite. Dôme, campanile, baptistère et musée : billet combiné €30." }, { heading: "Conseils Pratiques", content: "**Le billet de €30 comprend :** Montée au dôme (créneau à réserver en ligne), campanile, baptistère, musée et crypte. Valable 72h.\n\n**Ordre suggéré :** Dôme → Campanile → Cathédrale (gratuit) → Musée → Baptistère.\n\n**Code vestimentaire (strict) :** Épaules et genoux couverts. Pas de chapeau. Pour tous." }], faq: [{ q: "Combien coûtent les billets ?", a: "€30 combiné. La cathédrale est gratuite." }, { q: "Combien de marches pour le dôme ?", a: "463 sans ascenseur. 30-45 min. Réserver en ligne." }, { q: "La cathédrale est-elle gratuite ?", a: "Oui. Dôme, campanile, baptistère et musée : €30." }, { q: "Code vestimentaire ?", a: "Épaules et genoux couverts. Strictement appliqué." }, { q: "Dôme ou campanile ?", a: "Les deux si possible (même billet). Dôme = expérience d'ingénierie. Campanile = meilleure vue du dôme." }] },
  "restaurants-near-uffizi-gallery": { title: "Où Manger Près des Offices | 12 Restaurants Recommandés par un Local", description: "12 restaurants à 5 min des Offices recommandés par un guide local. Budget à gastronomique, plus gelato et café.", h1: "Où Manger Près des Offices — Guide d'un Local", heroImage: { src: "/images/blog/restaurants-near-uffizi-gallery/hero-trattoria-interior.webp", alt: "Intérieur d'une trattoria florentine traditionnelle", caption: "Oubliez les pièges à touristes — Florence a une cuisine extraordinaire si vous savez où chercher", width: 1200, height: 630 }, sections: [{ heading: "Repérer (et Éviter) les Pièges à Touristes", content: "**Signaux d'alerte :** Menus en 8+ langues avec photos, personnel qui vous interpelle, menu italien générique sans spécialités florentines.\n\n**Bons signes :** Menu en italien, clients locaux, plats du jour manuscrits, spécialités florentines (ribollita, lampredotto, bistecca).\n\n**Conseil :** Éloignez-vous de 2-3 rues de la Piazza della Signoria — la qualité monte et les prix baissent." }, { heading: "Gelato et Café", content: "**Gelato :** Bacs métalliques couverts, couleurs naturelles (pistache gris-vert, PAS vert vif).\n\n**Café comme un local :** Un caffè = espresso (€1-1,50 au comptoir). Cappuccino = uniquement avant 11h. Debout au comptoir = prix local.", image: { src: "/images/blog/restaurants-near-uffizi-gallery/section-gelato.webp", alt: "Gelato florentin authentique", caption: "Le vrai gelato — couleurs naturelles et saveur dense" } }], faq: [{ q: "Où manger près des Offices ?", a: "2-3 rues de la Piazza della Signoria. Vers Santa Croce ou Oltrarno." }, { q: "Combien coûte le déjeuner ?", a: "Sandwich : €5-8. Trattoria : €12-25. Pasta avec vin : ~€14-18." }, { q: "Plat typique florentin ?", a: "Ribollita, bistecca alla fiorentina, pappardelle al cinghiale, lampredotto." }, { q: "Comment trouver un bon gelato ?", a: "Bacs métalliques couverts avec couleurs naturelles." }, { q: "Faut-il réserver ?", a: "Pas pour le déjeuner. Recommandé pour le dîner en haute saison." }] },
  "florence-with-kids": { title: "Florence avec des Enfants 2026 | Musées, Repas et Activités en Famille", description: "Florence avec des enfants : meilleurs musées, activités et restaurants familiaux. Conseils par âge, parcours poussette et entrée gratuite moins de 18 ans.", h1: "Florence avec des Enfants 2026 — Guide Familial", heroImage: { src: "/images/blog/florence-with-kids/hero-family-florence.webp", alt: "Une famille sur une piazza de Florence avec le Dôme en arrière-plan", caption: "Florence avec des enfants — tout à fait faisable avec la bonne planification", width: 1200, height: 630 }, sections: [{ heading: "Oui, Vous Pouvez Amener des Enfants à Florence", content: "Florence a des places pour courir, du gelato à chaque coin, des musées scientifiques interactifs, des passages secrets et d'immenses jardins.\n\n**Plus grand avantage :** Tous les musées d'État italiens sont gratuits pour les moins de 18 ans, quelle que soit la nationalité. Une famille de quatre économise plus de €100 en entrées." }, { heading: "Les Offices avec des Enfants", content: "**Court !** Max 90 min sous 10 ans : Giotto (5 min), Botticelli (15 min), Léonard (10 min), terrasse-pause (15 min), Méduse de Caravage (10 min — les enfants adorent).\n\n**En faire un jeu.** Chasse au trésor : trouvez le tableau avec le coquillage, le bouclier avec le visage qui crie.\n\n**Créneau de 8h15.** Moins de stress pour les familles.\n\n**Moins de 18 = gratuit.** Pièce d'identité.", image: { src: "/images/blog/florence-with-kids/section-uffizi-terrace.webp", alt: "La terrasse des Offices avec des familles", caption: "La terrasse — l'arme secrète pour des enfants heureux" } }, { heading: "Conseils Pratiques pour les Familles", content: "**Poussettes :** Difficiles sur les pavés. Porte-bébé mieux pour moins de 3 ans.\n**Toilettes :** Dans les musées. Dans les cafés contre un café (€1).\n**Sécurité :** Florence est très sûre. Attention aux pickpockets en zones bondées.\n**Hébergement :** Appartement avec cuisine économise sur les petits-déjeuners. Oltrarno = meilleur quartier familial.\n**Lundi :** Offices et Accademia fermés. Alternatives : Palazzo Vecchio, Musée Galilée, Dôme, Boboli." }], faq: [{ q: "Florence est-elle adaptée aux enfants ?", a: "Oui — musées gratuits sous 18, gelato, musées interactifs, jardins." }, { q: "Les musées sont-ils gratuits pour les enfants ?", a: "Oui. Tous les musées d'État gratuits sous 18, toute nationalité." }, { q: "Meilleur musée pour enfants ?", a: "Musée Galilée (dès 5 ans). Pour tous : Accademia et Jardin de Boboli." }, { q: "Poussette aux Offices ?", a: "Techniquement oui, mais peu pratique. Porte-bébé mieux. Ascenseur disponible." }, { q: "Combien de musées par jour avec des enfants ?", a: "Un, max deux. Alterner avec plein air et gelato." }] },
};
